    """
    Each TDS section's rate, as the section held it, becomes a dated row (O233),
    from 1 April 2000 so no bill already booked falls before it, and NOT
    confirmed: nothing is deducted at it until the accountant confirms it or
    enters the law's rate from its own day. Seeded nothing as confirmed.
    """
    import datetime

    Section, Rate = apps.get_model("accounting", "TdsSection"), apps.get_model("accounting", "TdsRate")
    for section in Section.objects.order_by("pk"):
        Rate.objects.create(
            section=section, applies_from=datetime.date(2000, 4, 1), rate_percent=section.rate_percent,
            no_pan_rate_percent=section.no_pan_rate_percent,
            authority="As the section held it before rates were dated: confirm it, or enter the law's rate "
                      "from its day.")


